class Solution {
  private long[] cntIn, sumIn, cntOut, sumOut;
  private int size;
  private long[] valueAt;

  private void add(long[] cnt, long[] sum, int pos, int c, long v) {
    for (; pos <= size; pos += pos & -pos) {
      cnt[pos] += c;
      sum[pos] += c * v;
    }
  }

  // value at rank k (1-based among stored elements) and the sum of the k smallest
  private long[] kth(long[] cnt, long[] sum, int k, int top) {
    int pos = 0;
    long rem = k, acc = 0;
    for (int pw = top; pw > 0; pw >>= 1) {
      if (pos + pw <= size && cnt[pos + pw] < rem) {
        pos += pw;
        rem -= cnt[pos];
        acc += sum[pos];
      }
    }
    long value = valueAt[pos + 1];
    return new long[] {value, acc + value};
  }

  public long maxSum(int[] nums, int k) {
    int n = nums.length;
    Integer[] order = new Integer[n];
    for (int i = 0; i < n; i++) order[i] = i;
    java.util.Arrays.sort(order, (a, b) -> Integer.compare(nums[a], nums[b]));
    int[] rank = new int[n];
    valueAt = new long[n + 2];
    for (int r = 0; r < n; r++) {
      rank[order[r]] = r + 1;
      valueAt[r + 1] = nums[order[r]];
    }
    size = n;
    int top = 1;
    while ((top << 1) <= n) top <<= 1;
    long best = Long.MIN_VALUE;
    for (int l = 0; l < n; l++) {
      cntIn = new long[n + 1];
      sumIn = new long[n + 1];
      cntOut = new long[n + 1];
      sumOut = new long[n + 1];
      long totalOut = 0, inside = 0;
      for (int i = 0; i < n; i++) {
        add(cntOut, sumOut, rank[i], 1, nums[i]);
        totalOut += nums[i];
      }
      int inCount = 0, outCount = n;
      for (int r = l; r < n; r++) {
        add(cntOut, sumOut, rank[r], -1, nums[r]);
        add(cntIn, sumIn, rank[r], 1, nums[r]);
        totalOut -= nums[r];
        inside += nums[r];
        inCount++;
        outCount--;
        int tMax = Math.min(k, Math.min(inCount, outCount));
        int lo = 0, hi = tMax;
        while (lo < hi) {
          int mid = (lo + hi + 1) >>> 1;
          long smallestIn = kth(cntIn, sumIn, mid, top)[0];
          long largestOut = kth(cntOut, sumOut, outCount - mid + 1, top)[0];
          if (largestOut > smallestIn) lo = mid;
          else hi = mid - 1;
        }
        long gain = 0;
        if (lo > 0) {
          long sumSmallIn = kth(cntIn, sumIn, lo, top)[1];
          long sumBigOut =
              totalOut - (outCount - lo > 0 ? kth(cntOut, sumOut, outCount - lo, top)[1] : 0);
          gain = sumBigOut - sumSmallIn;
        }
        best = Math.max(best, inside + gain);
      }
    }
    return best;
  }
}
